import type { Fetch } from './fixtures'

export interface ConnectorConfig {
  githubWebhookSecret: string
  linearApiKey: string
  linearTeamId: string
  fetch?: Fetch
}

export interface GitHubIssuePayload {
  action: string
  issue: {
    title: string
    body: string | null
    labels: Array<{ name: string; color: string }>
    number: number
    user: { login: string }
  }
  repository: { full_name: string }
  sender: { login: string }
}

export interface LinearIssueResult {
  linearIssueId: string
  linearIssueTitle: string
}

async function verifySignature(
  payload: string,
  signature: string | null,
  secret: string,
): Promise<void> {
  if (!signature) {
    throw new Error('Missing X-Hub-Signature-256 header')
  }
  const expectedPrefix = 'sha256='
  if (!signature.startsWith(expectedPrefix)) {
    throw new Error('Invalid signature format')
  }
  const expectedSignature = signature.slice(expectedPrefix.length)
  const key = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  )
  const mac = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(payload))
  const actualSignature = Array.from(new Uint8Array(mac))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('')
  if (actualSignature !== expectedSignature) {
    throw new Error('Invalid webhook signature')
  }
}

function hasBugLabel(labels: Array<{ name: string }>): boolean {
  return labels.some((label) => label.name === 'bug')
}

function buildGraphQLMutation(input: {
  title: string
  description: string
  teamId: string
  labels: string[]
}): string {
  const escapedTitle = input.title.replace(/"/g, '\\"')
  const escapedDescription = input.description.replace(/"/g, '\\"')
  const labelsArray.fromCharCode/g, '\\u0000').replace(/"/g, '\\"')
  const labelsArray = input.labels.map((l) => `"${l.replace(/"/g, '\\"')}"`).join(', ')
  return `mutation IssueCreate { issueCreate(input: { title: "${escapedTitle}", description: "${escapedDescription}", teamId: "${input.teamId}", labels: [${labelsArray}] }) { success issue { id title } } }`
}

export async function handle(
  payload: GitHubIssuePayload,
  config: ConnectorConfig,
): Promise<LinearIssueResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.action) {
    throw new Error('Missing required field: action')
  }
  if (payload.action !== 'labeled') {
    throw new Error(`Unsupported action: ${payload.action}. Only 'labeled' is supported.`)
  }
  if (!payload.issue) {
    throw new Error('Missing required field: issue')
  }
  if (!payload.issue.title) {
    throw new Error('Missing required field: issue.title')
  }
  if (!payload.issue.labels || !Array.isArray(payload.issue.labels)) {
    throw new Error('Missing required field: issue.labels')
  }
  if (!hasBugLabel(payload.issue.labels)) {
    throw new Error("Issue does not have the 'bug' label")
  }
  if (typeof payload.issue.number !== 'number') {
    throw new Error('Missing required field: issue.number')
  }
  if (!payload.issue.user?.login) {
    throw new Error('Missing required field: issue.user.login')
  }

  const labels = payload.issue.labels.map((l) => l.name)
  const mutation = buildGraphQLMutation({
    title: payload.issue.title,
    description: payload.issue.body ?? '',
    teamId: config.linearTeamId,
    labels,
  })

  const response = await fetchImpl('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.linearApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ query: mutation }),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(
      `Linear API error: ${response.status} ${response.statusText} at POST https://api.linear.app/graphql - ${text}`,
    )
  }

  const data = (await response.json()) as {
    data?: { issueCreate?: { success: boolean; issue?: { id: string; title: string } } }
    errors?: Array<{ message: string }>
  }

  if (data.errors?.length) {
    throw new Error(`Linear API errors: ${data.errors.map((e) => e.message).join(', ')}`)
  }
  if (!data.data?.issueCreate?.success || !data.data.issueCreate.issue) {
    throw new Error('Linear API returned unexpected response structure')
  }

  return {
    linearIssueId: data.data.issueCreate.issue.id,
    linearIssueTitle: data.data.issueCreate.issue.title,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, type GitHubIssuePayload, type ConnectorConfig } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  type RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      githubWebhookSecret: 'test-secret',
      linearApiKey: 'test-api-key',
      linearTeamId: 'TRIAGE_TEAM_ID',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.linearIssueId).toBe('LI-123')
    expect(result.linearIssueTitle).toBe('Fix login button alignment')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql' && req.method === 'POST') {
        return jsonResponse({
          data: {
            issueCreate: {
              success: true,
              issue: { id: 'LI-456', title: 'Test Issue' },
            },
          },
        })
      }
      return jsonResponse({ error: 'Not found' }, 404)
    })
    calls = recordedCalls
    baseConfig = {
      githubWebhookSecret: 'test-secret',
      linearApiKey: 'test-api-key',
      linearTeamId: 'TRIAGE_TEAM_ID',
      fetch,
    }
  })

  it('creates a Linear issue with correct field mapping on happy path', async () => {
    const payload: GitHubIssuePayload = {
      action: 'labeled',
      issue: {
        title: 'Fix login button alignment',
        body: 'The login button is misaligned on mobile screens.',
        labels: [{ name: 'bug', color: 'd73a4a' }, { name: 'frontend', color: 'fbca04' }],
        number: 123,
        user: { login: 'alice-dev' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'alice-dev' },
    }

    const result = await handle(payload, baseConfig)

    expect(result.linearIssueId).toBe('LI-456')
    expect(result.linearIssueTitle).toBe('Test Issue')
    expect(calls.length).toBe(1)

    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.linear.app/graphql')
    expect(call.headers.get('authorization')).toBe('Bearer test-api-key')
    expect(call.headers.get('content-type')).toBe('application/json')

    const body = call.json as { query: string }
    expect(body.query).toContain('title: "Fix login button alignment"')
    expect(body.query).toContain('description: "The login button is misaligned on mobile screens."')
    expect(body.query).toContain('teamId: "TRIAGE_TEAM_ID"')
    expect(body.query).toContain('labels: ["bug", "frontend"]')
  })

  it('uses bearer token authentication for Linear API', async () => {
    const payload: GitHubIssuePayload = {
      action: 'labeled',
      issue: {
        title: 'Test',
        body: 'Body',
        labels: [{ name: 'bug', color: 'd73a4a' }],
        number: 1,
        user: { login: 'user' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'user' },
    }

    await handle(payload, baseConfig)

    const authHeader = calls[0].headers.get('authorization')
    expect(authHeader).toBe('Bearer test-api-key')
  })

  it('maps all required fields correctly', async () => {
    const payload: GitHubIssuePayload = {
      action: 'labeled',
      issue: {
        title: 'Issue Title',
        body: 'Issue description',
        labels: [{ name: 'bug', color: 'd73a4a' }, { name: 'urgent', color: 'ff0000' }],
        number: 42,
        user: { login: 'john-doe' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'john-doe' },
    }

    await handle(payload, baseConfig)

    const body = calls[0].json as { query: string }
    expect(body.query).toContain('title: "Issue Title"')
    expect(body.query).toContain('description: "Issue description"')
    expect(body.query).toContain('labels: ["bug", "urgent"]')
    expect(body.query).toContain('teamId: "TRIAGE_TEAM_ID"')
  })

  it('throws when action is missing', async () => {
    const payload = {
      issue: {
        title: 'Test',
        body: 'Body',
        labels: [{ name: 'bug', color: 'd73a4a' }],
        number: 1,
        user: { login: 'user' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'user' },
    } as unknown as GitHubIssuePayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: action')
  })

  it('throws when action is not labeled', async () => {
    const payload: GitHubIssuePayload = {
      action: 'opened',
      issue: {
        title: 'Test',
        body: 'Body',
        labels: [{ name: 'bug', color: 'd73a4a' }],
        number: 1,
        user: { login: 'user' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'user' },
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow("Unsupported action: opened. Only 'labeled' is supported.")
  })

  it('throws when issue is missing', async () => {
    const payload = {
      action: 'labeled',
      repository: { full_name: 'org/repo' },
      sender: { login: 'user' },
    } as unknown as GitHubIssuePayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: issue')
  })

  it('throws when issue.title is missing', async () => {
    const payload: GitHubIssuePayload = {
      action: 'labeled',
      issue: {
        title: '',
        body: 'Body',
        labels: [{ name: 'bug', color: 'd73a4a' }],
        number: 1,
        user: { login: 'user' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'user' },
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: issue.title')
  })

  it('throws when issue.labels is missing', async () => {
    const payload: GitHubIssuePayload = {
      action: 'labeled',
      issue: {
        title: 'Test',
        body: 'Body',
        labels: undefined as unknown as Array<{ name: string; color: string }>,
        number: 1,
        user: { login: 'user' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'user' },
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: issue.labels')
  })

  it('throws when issue does not have bug label', async () => {
    const payload: GitHubIssuePayload = {
      action: 'labeled',
      issue: {
        title: 'Test',
        body: 'Body',
        labels: [{ name: 'feature', color: 'fbca04' }],
        number: 1,
        user: { login: 'user' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'user' },
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow("Issue does not have the 'bug' label")
  })

  it('throws when issue.number is missing', async () => {
    const payload: GitHubIssuePayload = {
      action: 'labeled',
      issue: {
        title: 'Test',
        body: 'Body',
        labels: [{ name: 'bug', color: 'd73a4a' }],
        number: undefined as unknown as number,
        user: { login: 'user' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'user' },
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: issue.number')
  })

  it('throws when issue.user.login is missing', async () => {
    const payload: GitHubIssuePayload = {
      action: 'labeled',
      issue: {
        title: 'Test',
        body: 'Body',
        labels: [{ name: 'bug', color: 'd73a4a' }],
        number: 1,
        user: { login: '' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'user' },
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: issue.user.login')
  })

  it('throws on non-2xx response from Linear API', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() =>
      jsonResponse({ message: 'Invalid teamId' }, 400),
    )
    const config: ConnectorConfig = {
      ...baseConfig,
      fetch,
    }

    const payload: GitHubIssuePayload = {
      action: 'labeled',
      issue: {
        title: 'Test',
        body: 'Body',
        labels: [{ name: 'bug', color: 'd73a4a' }],
        number: 1,
        user: { login: 'user' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'user' },
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Linear API error: 400 Bad Request at POST https://api.linear.app/graphql',
    )
    expect(errorCalls.length).toBe(1)
  })

  it('throws when Linear API returns errors array', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() =>
      jsonResponse({
        errors: [{ message: 'Team not found' }, { message: 'Invalid label' }],
      }),
    )
    const config: ConnectorConfig = {
      ...baseConfig,
      fetch,
    }

    const payload: GitHubIssuePayload = {
      action: 'labeled',
      issue: {
        title: 'Test',
        body: 'Body',
        labels: [{ name: 'bug', color: 'd73a4a' }],
        number: 1,
        user: { login: 'user' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'user' },
    }

    await expect(handle(payload, config)).rejects.toThrow('Linear API errors: Team not found, Invalid label')
    expect(errorCalls.length).toBe(1)
  })

  it('throws when Linear API returns unexpected response structure', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() =>
      jsonResponse({ data: { issueCreate: { success: false } } }),
    )
    const config: ConnectorConfig = {
      ...baseConfig,
      fetch,
    }

    const payload: GitHubIssuePayload = {
      action: 'labeled',
      issue: {
        title: 'Test',
        body: 'Body',
        labels: [{ name: 'bug', color: 'd73a4a' }],
        number: 1,
        user: { login: 'user' },
      },
      repository: { full_name: 'org/repo' },
      sender: { login: 'user' },
    }

    await expect(handle(payload, config)).rejects.toThrow('Linear API returned unexpected response structure')
    expect(errorCalls.length).toBe(1)
  })
})

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://www.magicbell.com/blog/github-webhooks-guide
// Source: https://linear.app/developers/graphql

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "action": "labeled",
  "issue": {
    "title": "Fix login button alignment",
    "body": "The login button is misaligned on mobile screens. Needs CSS adjustment.",
    "labels": [
      {
        "name": "bug",
        "color": "d73a4a"
      },
      {
        "name": "frontend",
        "color": "fbca04"
      }
    ],
    "number": 123,
    "user": {
      "login": "alice-dev"
    }
  },
  "repository": {
    "full_name": "org/repo"
  },
  "sender": {
    "login": "alice-dev"
  }
}

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://api.linear.app/graphql",
    "response": {
      "data": {
        "issueCreate": {
          "success": true,
          "issue": {
            "id": "LI-123",
            "title": "Fix login button alignment"
          }
        }
      }
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

import type { Fetch } from './fixtures'

export interface ConnectorConfig {
  githubWebhookSecret: string
  linearApiKey: string
  linearTeamId: string
  fetch?: Fetch
  rawBody?: string
  signature?: string
}

export interface GitHubIssuePayload {
  action: string
  issue: {
    title: string
    body: string | null
    labels: Array<{ name: string; color: string }>
    number: number
    user: { login: string }
  }
  repository: { full_name: string }
  sender: { login: string }
}

export interface LinearIssueResult {
  linearIssueId: string
  linearIssueTitle: string
}

async function verifySignature(
  payload: string,
  signature: string | null,
  secret: string,
): Promise<void> {
  if (!signature) {
    throw new Error('Missing X-Hub-Signature-256 header')
  }
  const expectedPrefix = 'sha256='
  if (!signature.startsWith(expectedPrefix)) {
    throw new Error('Invalid signature format')
  }
  const expectedSignature = signature.slice(expectedPrefix.length)

  const cryptoGlobal = globalThis.crypto as
    | { subtle?: { importKey: Function; sign: Function } }
    | undefined
  if (!cryptoGlobal?.subtle) {
    throw new Error('Web Crypto API (crypto.subtle) not available. Ensure a polyfill like @peculiar/webcrypto is loaded.')
  }

  const key = await cryptoGlobal.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  )
  const mac = await cryptoGlobal.subtle.sign('HMAC', key, new TextEncoder().encode(payload))
  const actualSignature = Array.from(new Uint8Array(mac))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('')
  if (actualSignature !== expectedSignature) {
    throw new Error('Invalid webhook signature')
  }
}

function hasBugLabel(labels: Array<{ name: string }>): boolean {
  return labels.some((label) => label.name === 'bug')
}

function buildGraphQLMutation(input: {
  title: string
  description: string
  teamId: string
  labels: string[]
}): string {
  const escapedTitle = input.title.replace(/"/g, '\\"')
  const escapedDescription = input.description.replace(/"/g, '\\"')
  const labelsArray = input.labels.map((l) => `"${l.replace(/"/g, '\\"')}"`).join(', ')
  return `mutation IssueCreate { issueCreate(input: { title: "${escapedTitle}", description: "${escapedDescription}", teamId: "${input.teamId}", labels: [${labelsArray}] }) { success issue { id title } } }`
}

export async function handle(
  payload: GitHubIssuePayload,
  config: ConnectorConfig,
): Promise<LinearIssueResult> {
  const fetchImpl = config.fetch ?? fetch

  if (config.rawBody !== undefined && config.signature !== undefined) {
    await verifySignature(config.rawBody, config.signature, config.githubWebhookSecret)
  }

  if (!payload.action) {
    throw new Error('Missing required field: action')
  }
  if (payload.action !== 'labeled') {
    throw new Error(`Unsupported action: ${payload.action}. Only 'labeled' is supported.`)
  }
  if (!payload.issue) {
    throw new Error('Missing required field: issue')
  }
  if (!payload.issue.title) {
    throw new Error('Missing required field: issue.title')
  }
  if (!payload.issue.labels || !Array.isArray(payload.issue.labels)) {
    throw new Error('Missing required field: issue.labels')
  }
  if (!hasBugLabel(payload.issue.labels)) {
    throw new Error("Issue does not have the 'bug' label")
  }
  if (typeof payload.issue.number !== 'number') {
    throw new Error('Missing required field: issue.number')
  }
  if (!payload.issue.user?.login) {
    throw new Error('Missing required field: issue.user.login')
  }

  const labels = payload.issue.labels.map((l) => l.name)
  const mutation = buildGraphQLMutation({
    title: payload.issue.title,
    description: payload.issue.body ?? '',
    teamId: config.linearTeamId,
    labels,
  })

  const response = await fetchImpl('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.linearApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ query: mutation }),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(
      `Linear API error: ${response.status} ${response.statusText} at POST https://api.linear.app/graphql - ${text}`,
    )
  }

  const data = (await response.json()) as {
    data?: { issueCreate?: { success: boolean; issue?: { id: string; title: string } } }
    errors?: Array<{ message: string }>
  }

  if (data.errors?.length) {
    throw new Error(`Linear API errors: ${data.errors.map((e) => e.message).join(', ')}`)
  }
  if (!data.data?.issueCreate?.success || !data.data.issueCreate.issue) {
    throw new Error('Linear API returned unexpected response structure')
  }

  return {
    linearIssueId: data.data.issueCreate.issue.id,
    linearIssueTitle: data.data.issueCreate.issue.title,
  }
}

